package com.bank.spark.model;

// Represents one write-time partition directory (branch=Mumbai, etc.).
public class PartitionDir {
    private final String column;    // "branch"
    private final String value;     // "Mumbai"
    private final long sizeBytes;   // data size in this directory

    public PartitionDir(String column, String value, long sizeBytes) {
        this.column = column;
        this.value = value;
        this.sizeBytes = sizeBytes;
    }

    public String path() { return column + "=" + value; }
    public String getValue() { return value; }
    public long getSizeBytes() { return sizeBytes; }
}
