package com.bank.spark.service;

import com.bank.spark.model.PartitionDir;

import java.util.List;
import java.util.stream.Collectors;

// Simulates Catalyst partition pruning: keep only matching directories.
public class PartitionPruner {

    // Returns the directories that survive a filter on the partition column.
    public List<PartitionDir> prune(List<PartitionDir> all, String filterValue) {
        return all.stream()
                .filter(d -> d.getValue().equals(filterValue))
                .collect(Collectors.toList());
    }

    public long totalBytes(List<PartitionDir> dirs) {
        return dirs.stream().mapToLong(PartitionDir::getSizeBytes).sum();
    }
}
