package com.bank.spark;

import com.bank.spark.model.PartitionDir;
import com.bank.spark.service.PartitionPruner;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PartitionByDemo {

    private static final Logger log = Logger.getLogger(PartitionByDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PartitionPruner pruner = new PartitionPruner();

        // Simulate the directory layout written by partitionBy("branch").
        List<PartitionDir> all = List.of(
                new PartitionDir("branch", "Mumbai", 900_000_000L),
                new PartitionDir("branch", "Delhi", 750_000_000L),
                new PartitionDir("branch", "Chennai", 600_000_000L),
                new PartitionDir("branch", "Kolkata", 550_000_000L)
        );

        long fullScan = pruner.totalBytes(all);
        log.info(() -> "Full scan (no pruning): " + (fullScan / 1_000_000) + " MB across " + all.size() + " directories");

        // Query: WHERE branch = 'Mumbai'
        List<PartitionDir> kept = pruner.prune(all, "Mumbai");
        long prunedScan = pruner.totalBytes(kept);
        log.info(() -> "Pruned scan (branch=Mumbai): " + (prunedScan / 1_000_000) + " MB across "
                + kept.size() + " directory");
        log.info(() -> "Directories skipped: " + (all.size() - kept.size())
                + ", bytes saved: " + ((fullScan - prunedScan) / 1_000_000) + " MB");

        kept.forEach(d -> log.fine(() -> "Reading directory: " + d.path()));
        log.info("Partition pruning read only the Mumbai directory and skipped the rest.");
    }
}

